.peoplesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1b2240;
    background: linear-gradient(160deg, #eef0f8 0%, #e6eaf5 100%);
    border-radius: 18px;
}

.peoplesim-container * {
    box-sizing: border-box;
}

.peoplesim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #1a1f4b 0%, #2d3a86 55%, #1f7a8c 100%);
    color: #f4f6ff;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(26, 31, 75, 0.32);
}

.peoplesim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.peoplesim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #b6e3ec;
    background: rgba(255, 255, 255, 0.12);
    padding: 5px 14px;
    border-radius: 999px;
}

.peoplesim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #dde2f5;
}

.peoplesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2d3a86;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.peoplesim-period-counter #currentDay,
.peoplesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #1a1f4b;
}

.peoplesim-round-name {
    background: #d7defa;
    color: #1a1f4b;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.peoplesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9c4221;
    background: #fbe6db;
    padding: 4px 12px;
    border-radius: 999px;
}

.peoplesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.peoplesim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d9def0;
    box-shadow: 0 4px 14px rgba(26, 31, 75, 0.06);
    border-top: 4px solid #2d3a86;
}

.peoplesim-card-insight { border-top-color: #2d3a86; }
.peoplesim-card-causal { border-top-color: #1f7a8c; }
.peoplesim-card-adoption { border-top-color: #b7791f; }
.peoplesim-card-roi { border-top-color: #2f855a; }

.peoplesim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b7299;
}

.peoplesim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1a1f4b;
}

.peoplesim-card-insight .peoplesim-value { color: #2d3a86; }
.peoplesim-card-causal .peoplesim-value { color: #1f7a8c; }
.peoplesim-card-adoption .peoplesim-value { color: #b7791f; }
.peoplesim-card-roi .peoplesim-value { color: #2f855a; }

.peoplesim-sublabel {
    font-size: 0.76rem;
    color: #7b82a6;
    line-height: 1.35;
}

.peoplesim-roi-negative .peoplesim-value { color: #c0392b; }
.peoplesim-roi-strong .peoplesim-value { color: #2f855a; }

.peoplesim-budget-over { border-top-color: #c0392b; }
.peoplesim-budget-over .peoplesim-value { color: #c0392b; }

.peoplesim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1a1f4b;
    color: #eaeefb;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.peoplesim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.peoplesim-budget-bar.peoplesim-budget-bar-over #budgetDisplay {
    color: #ff9b8a;
}

.peoplesim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #1f7a8c;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(26, 31, 75, 0.05);
}

.peoplesim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.peoplesim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1a1f4b;
    margin-bottom: 6px;
}

.peoplesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #353c63;
}

.peoplesim-briefing-text strong { color: #2f855a; }
.peoplesim-briefing-text em { color: #9c4221; font-style: italic; }

.peoplesim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d9def0;
    box-shadow: 0 4px 14px rgba(26, 31, 75, 0.06);
}

.peoplesim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1a1f4b;
    border-bottom: 2px solid #e6eaf5;
    padding-bottom: 8px;
}

.peoplesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #28305c;
    margin: 14px 0 6px;
}

.peoplesim-container select,
.peoplesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #bcc4e3;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f6f8fe;
    color: #1b2240;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.peoplesim-container select:focus,
.peoplesim-container input[type="number"]:focus {
    outline: none;
    border-color: #1f7a8c;
    box-shadow: 0 0 0 3px rgba(31, 122, 140, 0.15);
}

.peoplesim-container select option {
    background-color: #ffffff;
    color: #1b2240;
}

.peoplesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #1f7a8c;
}

.peoplesim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2d3a86;
    margin-top: 4px;
}

.peoplesim-range-readout span:last-child {
    color: #2f855a;
    font-weight: 800;
}

.peoplesim-hint {
    font-size: 0.8rem;
    color: #7b82a6;
    margin-top: 4px;
    line-height: 1.4;
}

.peoplesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.peoplesim-container .btn-primary {
    background: linear-gradient(135deg, #2f855a 0%, #1f7a8c 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(47, 133, 90, 0.28);
}

.peoplesim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.peoplesim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #bcc4e3;
    color: #6b7299;
}

.peoplesim-coach {
    background: #1a1f4b;
    color: #eaeefb;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(26, 31, 75, 0.24);
}

.peoplesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #7fd0dd;
    margin-bottom: 8px;
}

.peoplesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.peoplesim-coach-body strong { color: #ffd98a; }
.peoplesim-coach-body em { color: #ffc1ad; font-style: italic; }

.peoplesim-history,
.peoplesim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d9def0;
    box-shadow: 0 4px 14px rgba(26, 31, 75, 0.06);
}

.peoplesim-history h3,
.peoplesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1a1f4b;
}

.peoplesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #28305c;
}

.peoplesim-container table#usfHistoryTable th {
    background: #eaedf9;
    color: #1a1f4b;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d4dbf2;
}

.peoplesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef1fa;
}

.peoplesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7f9fe;
}

.peoplesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .peoplesim-container {
        padding: 14px;
    }
    .peoplesim-header h1 {
        font-size: 1.7rem;
    }
    .peoplesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .peoplesim-value {
        font-size: 2rem;
    }
    .peoplesim-clock {
        margin-left: 0;
    }
    .peoplesim-period-counter {
        font-size: 0.88rem;
    }
    .peoplesim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .peoplesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion-message card (appended; dark-on-light, self-contained) */
.peoplesim-cm { background:#f3f5fa; color:#161b2b; border-radius:14px; padding:22px 24px; max-width:640px; margin:0 auto; font-family:inherit; box-shadow:0 8px 30px rgba(0,0,0,0.18); }
.peoplesim-cm-head { text-align:center; border-bottom:1px solid #d9deed; padding-bottom:14px; margin-bottom:16px; }
.peoplesim-cm-title { font-size:13px; letter-spacing:.08em; text-transform:uppercase; color:#535a78; font-weight:700; }
.peoplesim-cm-scorewrap { margin:8px 0 2px; }
.peoplesim-cm-score { font-size:52px; font-weight:800; color:#3f5bb0; line-height:1; }
.peoplesim-cm-score-max { font-size:20px; color:#8890ac; font-weight:600; }
.peoplesim-cm-grade { font-size:19px; font-weight:700; color:#161b2b; margin-top:4px; }
.peoplesim-cm-badges { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; justify-content:center; }
.peoplesim-cm-badge { font-size:12px; font-weight:700; padding:4px 11px; border-radius:999px; }
.peoplesim-cm-met { background:#d2e9dc; color:#1b6a4c; }
.peoplesim-cm-fail { background:#f2dbd9; color:#a1362f; }
.peoplesim-cm-metrics { display:flex; flex-wrap:wrap; gap:12px; justify-content:center; margin-bottom:16px; }
.peoplesim-cm-metric { background:#e6e9f4; border-radius:10px; padding:12px 16px; min-width:104px; text-align:center; }
.peoplesim-cm-metric-val { font-size:22px; font-weight:800; color:#161b2b; }
.peoplesim-cm-metric-lbl { font-size:11px; letter-spacing:.05em; text-transform:uppercase; color:#535a78; margin-top:3px; }
.peoplesim-cm-insights { background:#e6e9f4; border-radius:10px; padding:14px 18px; }
.peoplesim-cm-insights-title { font-size:12px; letter-spacing:.06em; text-transform:uppercase; color:#535a78; font-weight:700; margin-bottom:8px; }
.peoplesim-cm-insights ul { margin:0; padding-left:18px; }
.peoplesim-cm-insights li { font-size:14px; line-height:1.5; color:#2b3040; margin-bottom:7px; }

