(function() {
    'use strict';

    class PeopleAnalyticsAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Analytics-Led HR`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (R$, in millions where noted).
            this.BUDGET_CAP = 22;            // R$22M frozen flat
            this.COST_ENGAGEMENT = 6;        // Intervention A
            this.COST_MANAGER = 3;           // Intervention B
            this.COST_STAFFING = 2;          // Intervention C
            this.COST_BONUS = 8;             // Intervention D
            this.COST_MEASUREMENT = 2;       // control group / staggered design
            this.EXITS_PER_YEAR = 400;       // regretted high-performer exits
            this.COST_PER_EXIT = 0.18;       // R$180k = R$0.18M per exit
            this.START_TURNOVER = 24;        // %
            this.ROI_TARGET = 8;             // R$8M net/yr = a CFO-defensible win

            // Concept-correct answers.
            this.TRUE_SEGMENT = `overutil`;
            this.TRUE_DRIVER = `utilmanager`;
            this.TRUE_QUESTION = `narrow`;
            this.CAUSE_INTERVENTIONS = [`manager`, `staffing`];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    insight: 12,
                    causal: 8,
                    adoption: 15,
                    roi: 0,
                    budgetUsed: 0,
                    chosenIntervention: ``,
                    correlationTrap: false,
                    diffuseSpend: false,
                    insightHistory: [12],
                    causalHistory: [8],
                    adoptionHistory: [15],
                    roiHistory: [0],
                    lastCoach: ``,
                    targetMissed: false
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults = a middling/neutral mix (NOT the textbook play).
                state.decisions = {
                    segment: `firmwide`,
                    driver: `engagement`,
                    rigor: 50,
                    question: `engagement`,
                    intervention: `engagement`,
                    mechanism: `correlation`,
                    adoptionRisk: 50,
                    measurement: `prepost`,
                    focus: `spread`,
                    target: 3,
                    sensitivity: 50,
                    adoptionMech: `train`,
                    leading: `lagging`,
                    pitch: `hedge`,
                    capability: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const seg = document.getElementById(`segmentInput`);
                const drv = document.getElementById(`driverInput`);
                const rig = document.getElementById(`rigorInput`);
                if (seg) decisions.segment = seg.value;
                if (drv) decisions.driver = drv.value;
                if (rig) decisions.rigor = parseInt(rig.value, 10);
                if (!Number.isFinite(decisions.rigor) || decisions.rigor < 0 || decisions.rigor > 100) {
                    warn(`warn_rigor_range`); return false;
                }
            } else if (round === 2) {
                const q = document.getElementById(`questionInput`);
                const int = document.getElementById(`interventionInput`);
                const mech = document.getElementById(`mechanismInput`);
                const ar = document.getElementById(`adoptionRiskInput`);
                if (q) decisions.question = q.value;
                if (int) decisions.intervention = int.value;
                if (mech) decisions.mechanism = mech.value;
                if (ar) decisions.adoptionRisk = parseInt(ar.value, 10);
                if (!Number.isFinite(decisions.adoptionRisk) || decisions.adoptionRisk < 0 || decisions.adoptionRisk > 100) {
                    warn(`warn_adoptionrisk_range`); return false;
                }
            } else if (round === 3) {
                const meas = document.getElementById(`measurementInput`);
                const foc = document.getElementById(`focusInput`);
                const tgt = document.getElementById(`targetInput`);
                const sens = document.getElementById(`sensitivityInput`);
                if (meas) decisions.measurement = meas.value;
                if (foc) decisions.focus = foc.value;
                if (tgt) decisions.target = parseFloat(tgt.value);
                if (sens) decisions.sensitivity = parseInt(sens.value, 10);
                if (!Number.isFinite(decisions.target) || decisions.target < 0 || decisions.target > 15) {
                    warn(`warn_target_range`); return false;
                }
                if (!Number.isFinite(decisions.sensitivity) || decisions.sensitivity < 0 || decisions.sensitivity > 100) {
                    warn(`warn_sensitivity_range`); return false;
                }
            } else if (round === 4) {
                const am = document.getElementById(`adoptionMechInput`);
                const ld = document.getElementById(`leadingInput`);
                const pt = document.getElementById(`pitchInput`);
                const cap = document.getElementById(`capabilityInput`);
                if (am) decisions.adoptionMech = am.value;
                if (ld) decisions.leading = ld.value;
                if (pt) decisions.pitch = pt.value;
                if (cap) decisions.capability = parseInt(cap.value, 10);
                if (!Number.isFinite(decisions.capability) || decisions.capability < 0 || decisions.capability > 100) {
                    warn(`warn_capability_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let insightDelta = 0, causalDelta = 0, adoptionDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Mine the data: locate WHERE the firm loses high performers (Common Error 1).
                if (d.segment === this.TRUE_SEGMENT) {
                    insightDelta += 14; causalDelta += 3; coachKey = `coach_r1_segment_right`;
                } else if (d.segment === `firmwide`) {
                    insightDelta -= 10; coachKey = `coach_r1_firmwide`;
                } else if (d.segment === `pay`) {
                    insightDelta -= 6; coachKey = `coach_r1_pay`;
                } else {
                    insightDelta -= 4; coachKey = `coach_r1_juniors`;
                }

                // Which factors travel with regretted exits — cause vs the loud correlate.
                if (d.driver === this.TRUE_DRIVER) {
                    insightDelta += 8; causalDelta += 7;
                    if (d.segment === this.TRUE_SEGMENT) coachKey = `coach_r1_diag_sharp`;
                } else if (d.driver === `engagement`) {
                    insightDelta -= 4; causalDelta -= 6; coachKey = `coach_r1_engagement`;
                } else if (d.driver === `tenure`) {
                    causalDelta -= 4;
                } else {
                    insightDelta -= 8; causalDelta -= 8; coachKey = `coach_r1_random`;
                }

                // Rigor: separating plausible causes from mere correlates.
                if (d.rigor >= 60) { causalDelta += 6; }
                else if (d.rigor <= 25) { causalDelta -= 8; coachKey = `coach_r1_lowrigor`; }

                summaryKey = (d.segment === this.TRUE_SEGMENT && d.driver === this.TRUE_DRIVER) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Frame the right question + pick ONE cause-addressing intervention (Errors 1 & 2).
                if (d.question === this.TRUE_QUESTION) {
                    insightDelta += 12; causalDelta += 3; coachKey = `coach_r2_narrow`;
                } else if (d.question === `engagement`) {
                    insightDelta -= 10; coachKey = `coach_r2_engagementq`;
                } else if (d.question === `benchmark`) {
                    insightDelta -= 4; coachKey = `coach_r2_benchmark`;
                } else {
                    insightDelta -= 8; coachKey = `coach_r2_dashboard`;
                }

                ds.chosenIntervention = d.intervention;
                switch (d.intervention) {
                    case `manager`:
                        insightDelta += 6; causalDelta += 6; adoptionDelta += 7; coachKey = `coach_r2_manager`; break;
                    case `staffing`:
                        insightDelta += 5; causalDelta += 5; adoptionDelta += 9; coachKey = `coach_r2_staffing`; break;
                    case `engagement`:
                        insightDelta -= 6; causalDelta -= 6; coachKey = `coach_r2_engagementint`; break;
                    case `bonus`:
                        insightDelta -= 8; causalDelta -= 10; adoptionDelta += 2; coachKey = `coach_r2_bonus`; break;
                }

                // Causal mechanism: addressing the cause vs chasing a correlation (Error 3 seed).
                switch (d.mechanism) {
                    case `cause`: causalDelta += 8; insightDelta += 3; break;
                    case `correlation`: causalDelta -= 8; coachKey = `coach_r2_mechcorrelation`; break;
                    case `buy`: causalDelta -= 6; adoptionDelta -= 2; coachKey = `coach_r2_mechbuy`; break;
                }

                // Flagging adoption risk early (Error 4 seed).
                if (d.adoptionRisk >= 60) { adoptionDelta += 10; }
                else if (d.adoptionRisk <= 25) { adoptionDelta -= 6; coachKey = `coach_r2_lowadoptionrisk`; }

                const causeChosen = this.CAUSE_INTERVENTIONS.indexOf(d.intervention) !== -1;
                summaryKey = (d.question === this.TRUE_QUESTION && causeChosen && d.mechanism === `cause`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Measurement design = the price of a defensible causal ROI (Error 3).
                switch (d.measurement) {
                    case `staggered`: spend += this.COST_MEASUREMENT; causalDelta += 13; insightDelta += 3; coachKey = `coach_r3_staggered`; break;
                    case `prepost`: causalDelta -= 4; coachKey = `coach_r3_prepost`; break;
                    case `none`: causalDelta -= 14; ds.correlationTrap = true; coachKey = `coach_r3_nomeasure`; break;
                }

                // Spend the frozen envelope: focus vs diffuse (Error 5).
                const intCost = this._interventionCost(ds.chosenIntervention);
                switch (d.focus) {
                    case `focused`:
                        spend += intCost; insightDelta += 7; causalDelta += 5; adoptionDelta += 3; coachKey = `coach_r3_focused`; break;
                    case `twolever`:
                        // Both cause-addressing levers together — still a focused, defensible bet.
                        spend += (this.COST_MANAGER + this.COST_STAFFING); insightDelta += 6; causalDelta += 4; adoptionDelta += 5; coachKey = `coach_r3_twolever`; break;
                    case `spread`:
                        spend += (this.COST_ENGAGEMENT + this.COST_MANAGER + this.COST_STAFFING + this.COST_BONUS);
                        insightDelta -= 12; causalDelta -= 12; ds.diffuseSpend = true; coachKey = `coach_r3_spread`; break;
                }

                // Sensitivity range: speaking finance's language.
                if (d.sensitivity >= 60) { insightDelta += 5; causalDelta += 3; }
                else if (d.sensitivity <= 25) { causalDelta -= 4; coachKey = `coach_r3_lowsensitivity`; }

                summaryKey = (d.measurement === `staggered` && (d.focus === `focused` || d.focus === `twolever`)) ? `sum_r3_good` : `sum_r3_weak`;
            } else if (round === 4) {
                // Adoption mechanics — an unadopted intervention has zero ROI (Error 4).
                switch (d.adoptionMech) {
                    case `billability`: adoptionDelta += 22; insightDelta += 3; coachKey = `coach_r4_billability`; break;
                    case `train`: adoptionDelta += 4; coachKey = `coach_r4_train`; break;
                    case `mandate`: adoptionDelta -= 6; coachKey = `coach_r4_mandate`; break;
                    case `none`: adoptionDelta -= 12; coachKey = `coach_r4_noadopt`; break;
                }

                // Leading indicators before the lagging ROI lands.
                switch (d.leading) {
                    case `leading`: causalDelta += 7; insightDelta += 5; break;
                    case `lagging`: causalDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r4_lagging` : coachKey; break;
                    case `vanity`: causalDelta -= 6; insightDelta -= 4; coachKey = `coach_r4_vanity`; break;
                }

                // The CFO challenge: defend the single-intervention focus and the causal claim.
                switch (d.pitch) {
                    case `focus`: insightDelta += 7; causalDelta += 6; adoptionDelta += 6; coachKey = (d.adoptionMech === `billability`) ? `coach_r4_focus` : coachKey; break;
                    case `hedge`: insightDelta -= 10; causalDelta -= 8; coachKey = `coach_r4_hedge`; break;
                    case `correlation`: causalDelta -= 12; ds.correlationTrap = true; coachKey = `coach_r4_pitchcorrelation`; break;
                }

                // Analytics-capability commitment nudges insight.
                insightDelta += Math.round((d.capability - 50) / 10);

                summaryKey = (d.adoptionMech === `billability` && d.leading === `leading` && d.pitch === `focus`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting (R$ millions). Spend is cumulative across rounds.
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 100) / 100;

            // KPI meters move on their deltas (kept 0–100, low start + headroom).
            ds.insight = Math.max(0, Math.min(100, ds.insight + insightDelta));
            ds.causal = Math.max(0, Math.min(100, ds.causal + causalDelta));
            ds.adoption = Math.max(0, Math.min(100, ds.adoption + adoptionDelta));

            // ROI: net annual R$M the CFO will recognise. It is only as real as the three
            // pillars behind it — insight (right target), causal confidence (proven effect)
            // and manager adoption (the intervention is actually used). A correlation claim or
            // a budget overrun guts the credible, defensible ROI.
            ds.roi = this._computeRoi(state, ds);

            ds.insightHistory.push(Math.round(ds.insight));
            ds.causalHistory.push(Math.round(ds.causal));
            ds.adoptionHistory.push(Math.round(ds.adoption));
            ds.roiHistory.push(Math.round(ds.roi * 10) / 10);

            if (round === this.ROUNDS.length && ds.roi < this.ROI_TARGET) ds.targetMissed = true;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            // v1.1.0 fix: persist instructor-card composite to domainState every period.
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                insight: Math.round(ds.insight),
                insightDelta: Math.round(insightDelta),
                causal: Math.round(ds.causal),
                causalDelta: Math.round(causalDelta),
                adoption: Math.round(ds.adoption),
                adoptionDelta: Math.round(adoptionDelta),
                roi: Math.round(ds.roi * 10) / 10,
                budgetUsed: ds.budgetUsed,
                correlationTrap: ds.correlationTrap,
                diffuseSpend: ds.diffuseSpend,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _interventionCost(intervention) {
            switch (intervention) {
                case `manager`: return this.COST_MANAGER;
                case `staffing`: return this.COST_STAFFING;
                case `engagement`: return this.COST_ENGAGEMENT;
                case `bonus`: return this.COST_BONUS;
                default: return 0;
            }
        }

        _computeRoi(state, ds) {
            const d = state.decisions;
            const target = Number.isFinite(d.target) ? d.target : 0;

            // Gross prize: each point of attrition cut in the segment avoids ~R$3M
            // (≈ EXITS_PER_YEAR / START_TURNOVER × COST_PER_EXIT per point).
            const perPoint = (this.EXITS_PER_YEAR / this.START_TURNOVER) * this.COST_PER_EXIT; // ≈ 3.0
            let gross = target * perPoint;

            // Credibility multiplier: the avoided attrition is only believable to the extent
            // the analytics targeted the real driver (insight), the effect is measured
            // (causal) and managers actually adopt it (adoption). All three start low, so a
            // wrong strategy keeps the credible prize small right through the final round.
            const credibility = (ds.insight / 100) * 0.4 + (ds.causal / 100) * 0.4 + (ds.adoption / 100) * 0.2;
            let credibleGross = gross * credibility;

            // Symptom-buying (bonuses) and correlation claims further discount the prize:
            // the CFO will not recognise attrition "avoided" by a pause she can't attribute.
            if (ds.chosenIntervention === `bonus`) credibleGross *= 0.5;
            if (ds.correlationTrap) credibleGross *= 0.45;

            // Net of the committed cost.
            let net = credibleGross - ds.budgetUsed;

            // Overrunning the frozen envelope is itself a failure the CFO froze to prevent.
            if (ds.budgetUsed > this.BUDGET_CAP + 0.001) net -= (ds.budgetUsed - this.BUDGET_CAP) * 1.5;

            return Math.round(net * 10) / 10;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);
            uiManager.bind(`insightDisplay`, `domainState.insight`, (v) => Math.round(v));
            uiManager.bind(`causalDisplay`, `domainState.causal`, (v) => Math.round(v));
            uiManager.bind(`adoptionDisplay`, `domainState.adoption`, (v) => Math.round(v));
            uiManager.bind(`roiDisplay`, `domainState.roi`, (v) => {
                const card = document.querySelector(`.peoplesim-card-roi`);
                if (card) {
                    card.classList.toggle(`peoplesim-roi-strong`, Number(v) >= this.ROI_TARGET);
                    card.classList.toggle(`peoplesim-roi-negative`, Number(v) < 0);
                }
                return this._fmtRoi(Number(v));
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const bar = document.querySelector(`.peoplesim-budget-bar`);
                if (bar) bar.classList.toggle(`peoplesim-budget-bar-over`, Number(v) > this.BUDGET_CAP + 0.001);
                const card = document.querySelector(`.peoplesim-card-roi`);
                if (card) card.classList.toggle(`peoplesim-budget-over`, false);
                return `R$` + this._fmtNum(Number(v)) + `M / R$22M`;
            });

            // Slider live readouts.
            const pairs = [
                [`rigorInput`, `rigorReadout`],
                [`adoptionRiskInput`, `adoptionRiskReadout`],
                [`sensitivityInput`, `sensitivityReadout`]
            ];
            pairs.forEach(([inId, outId]) => {
                const inEl = document.getElementById(inId);
                const outEl = document.getElementById(outId);
                if (inEl && outEl) {
                    outEl.textContent = inEl.value;
                    inEl.addEventListener(`input`, function() { outEl.textContent = inEl.value; });
                }
            });
        }

        _fmtNum(v) {
            // Brazilian decimal comma; trim a trailing ,0.
            const s = (Math.round(v * 10) / 10).toFixed(1).replace(`.`, `,`);
            return s.endsWith(`,0`) ? s.slice(0, -2) : s;
        }

        _fmtRoi(v) {
            const neg = v < 0;
            return (neg ? `-R$` : `R$`) + this._fmtNum(Math.abs(v)) + `M`;
        }

