        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.insightHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : window.mySimulation.t(`chart_round_prefix`) + i));
            return {
                peopleChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.insightHistory },
                        { data: ds.causalHistory },
                        { data: ds.adoptionHistory },
                        { data: ds.roiHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.0.0 composite formula, verbatim — single source of truth.
            const insight = Math.round(ds.insight);
            const causal = Math.round(ds.causal);
            const adoption = Math.round(ds.adoption);
            const roi = Math.round(ds.roi * 10) / 10;
            return Math.round(insight * 0.3 + causal * 0.3 + adoption * 0.2 + Math.max(0, Math.min(100, (roi / 30) * 100)) * 0.2);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const insight = Math.round(ds.insight);
            const causal = Math.round(ds.causal);
            const adoption = Math.round(ds.adoption);
            const roi = Math.round(ds.roi * 10) / 10;

            const hitTarget = roi >= this.ROI_TARGET;
            const defensible = causal >= 60 && adoption >= 55;
            const composite = this._composite(ds);

            let performanceKey = `grade_cut`;
            if (hitTarget && defensible && composite >= 70) performanceKey = `grade_seat`;
            else if (hitTarget && defensible) performanceKey = `grade_defensible`;
            else if (hitTarget && ds.correlationTrap) performanceKey = `grade_cfo`;
            else if (hitTarget) performanceKey = `grade_thin`;
            else if (roi > 0) performanceKey = `grade_positive`;
            const met = hitTarget && defensible && composite >= 70;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (hitTarget && defensible) insights.push(window.mySimulation.t(`insight_seat`));
            else if (ds.correlationTrap) insights.push(window.mySimulation.t(`insight_correlation`));
            else if (hitTarget) insights.push(window.mySimulation.t(`insight_thin`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.diffuseSpend) insights.push(window.mySimulation.t(`insight_diffuse`));
            if (ds.chosenIntervention === `bonus`) insights.push(window.mySimulation.t(`insight_bonus`));
            if (adoption < 45) insights.push(window.mySimulation.t(`insight_lowadoption`));
            if (hitTarget && defensible && insight >= 70) insights.push(window.mySimulation.t(`insight_rightquestion`));

            return {
                insight: insight,
                causal: causal,
                adoption: adoption,
                roi: roi,
                hitTarget: hitTarget,
                defensible: defensible,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                correlationTrap: !!ds.correlationTrap,
                diffuseSpend: !!ds.diffuseSpend,
                chosenIntervention: ds.chosenIntervention,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k, v) => window.mySimulation.t(k, v);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="peoplesim-cm-badge ` + (s.met ? `peoplesim-cm-met` : `peoplesim-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.correlationTrap) badges.push(`<span class="peoplesim-cm-badge peoplesim-cm-fail">` + t(`cm_fail_correlation`) + `</span>`);
            if (s.diffuseSpend) badges.push(`<span class="peoplesim-cm-badge peoplesim-cm-fail">` + t(`cm_fail_diffuse`) + `</span>`);
            if (s.defensible === false) badges.push(`<span class="peoplesim-cm-badge peoplesim-cm-fail">` + t(`cm_fail_defensible`) + `</span>`);
            if (s.hitTarget === false) badges.push(`<span class="peoplesim-cm-badge peoplesim-cm-fail">` + t(`cm_fail_target`) + `</span>`);
            const kpi = (label, val) => `<div class="peoplesim-cm-metric"><div class="peoplesim-cm-metric-val">` + val + `</div><div class="peoplesim-cm-metric-lbl">` + label + `</div></div>`;
            const roiv = (s.roi != null) ? ((s.roi < 0 ? `-R$` : `R$`) + Math.abs(s.roi) + `M`) : ``;
            const kpis = kpi(t(`cm_insight`), (s.insight != null ? Math.round(s.insight) : 0))
                + kpi(t(`cm_causal`), (s.causal != null ? Math.round(s.causal) : 0))
                + kpi(t(`cm_adoption`), (s.adoption != null ? Math.round(s.adoption) : 0))
                + kpi(t(`cm_roi`), roiv);
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="peoplesim-cm">`
                + `<div class="peoplesim-cm-head"><div class="peoplesim-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="peoplesim-cm-scorewrap"><span class="peoplesim-cm-score">` + score + `</span><span class="peoplesim-cm-score-max">/100</span></div>`
                + `<div class="peoplesim-cm-grade">` + grade + `</div>`
                + `<div class="peoplesim-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="peoplesim-cm-metrics">` + kpis + `</div>`
                + `<div class="peoplesim-cm-insights"><div class="peoplesim-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
