            if (ds.adoption < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_adoption`);
            if (ds.causal < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_causal`);
            if (state.currentPeriod >= 3 && ds.roi < this.ROI_TARGET) return window.mySimulation.t(`hint_behind`);
            if (ds.roi >= this.ROI_TARGET && ds.causal >= 60 && ds.adoption >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

