                    warn_rigor_range:       `Tu disciplina causa-vs-correlación debe ser un porcentaje entre 0 y 100.`,
                    warn_adoptionrisk_range:`Tu atención al riesgo de adopción debe ser un porcentaje entre 0 y 100.`,
